use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-g2-owned-finish");let mut p:Value=serde_json::from_str(&serde_json::to_string(&read("/tmp/zopro-streamed-complex-sdk/native-plan.json")).unwrap().replace("/tmp/zopro-streamed-complex-sdk","/tmp/zopro-g2-owned-finish").replace("zopro_streamed_complex_b","zopro_g2_owned_finish")).unwrap();for s in p["steps"].as_array_mut().unwrap(){if s["name"]=="on-core"{let tests=s["required_tests"].as_array_mut().unwrap();for t in["msm::g2_owned_finish::tests::full_batches_match_generator_oracle_and_consume_only_x","msm::g2_owned_finish::tests::fallbacks_preserve_incoming_points_and_match_complete_addition","msm::g2_owned_finish::tests::reused_owned_scratch_preserves_layer_and_bucket_contract"]{tests.push(json!(t));}}}
let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=BTreeMap::new();for(n,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(n)),h.as_str().unwrap());let p=r.join("candidate").join(n);pins.insert(p.to_str().unwrap().to_owned(),hash(p));}for name in["crates/zopro-core/src/msm/g2_owned_finish.rs","crates/zopro-core/src/msm/g2_owned_finish/tests.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{let p=r.join("candidate").join(name);pins.insert(p.to_str().unwrap().into(),hash(&p));}assert_eq!(pins.len(),174);for name in["experiment.json","design.md","prepare.json","implement.rs","source-audit.json","prepare-build.rs","g2_owned_finish.rs.txt","tests.rs.txt"]{let p=r.join(name);pins.insert(p.to_str().unwrap().into(),hash(&p));}for path in["/tmp/zopro-grouping-module/production-source-manifest.json","/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask","/tmp/zopro-front-end-counters/analysis.json","/tmp/zopro-front-end-counters/event-definitions.json"]{pins.insert(path.into(),hash(path));}p["source_pins"]=json!(r.join("build-input-pins.json"));fs::write(r.join("build-input-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("native-plan.json"),serde_json::to_vec_pretty(&p).unwrap()).unwrap();fs::write(r.join("work-state.json"),serde_json::to_vec_pretty(&json!({"phase":"native OFF/ON correctness+actualSDKbuild","source_pins":174,"build_pins":pins.len(),"candidate":r.join("candidate"),"field_arithmetic_unchanged":true,"adopted":false,"goal_achieved":false,"last_pushed_commit":"85d5db827ef903dd05930692d6b0d51850d1a0e2"})).unwrap()).unwrap();println!("Frozen174sources{}buildpins, actualOFF/ONSDK and3independentowned-batchtests; no componentbenchmark",pins.len());}
